CREATE TABLE financial_reports (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>0), from_date TEXT NOT NULL CHECK(length(from_date)=10), to_date TEXT NOT NULL CHECK(length(to_date)=10 AND to_date>=from_date), updated_at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL CHECK(json_valid(data)), CHECK(json_extract(data,'$.id') IS id AND json_extract(data,'$.version') IS version AND json_extract(data,'$.from') IS from_date AND json_extract(data,'$.to') IS to_date)) STRICT;
CREATE INDEX financial_reports_period ON financial_reports(from_date,to_date);
